cssCode:
.chart-container {
  display: flex; align-items: flex-end; gap: 15px;
  width: 200px; height: 150px;
  border-bottom: 2px solid #333; border-left: 2px solid #333;
  padding: 10px; box-sizing: border-box;
}
.chart-bar {
  width: 40px; background: linear-gradient(to top, #00b09b, #96c93d);
  border-radius: 5px 5px 0 0;
  box-shadow: 0 0 15px rgba(0, 176, 155, 0.5);
  animation: growBar 1.5s cubic-bezier(0.175, 0.885, 0.32, 1.275) forwards;
  transform-origin: bottom; transform: scaleY(0);
}
@keyframes growBar {
  100% { transform: scaleY(1); }
}

jsCode:
const c = document.getElementById('container');
c.style.cssText = 'width:100%;height:100%;display:flex;align-items:center;justify-content:center;background:transparent;';

const chart = document.createElement('div');
chart.className = 'chart-container';

const heights = ['40%', '65%', '95%'];
heights.forEach((h, i) => {
  const bar = document.createElement('div');
  bar.className = 'chart-bar';
  bar.style.height = h;
  bar.style.animationDelay = `${i * 0.3}s`;
  chart.appendChild(bar);
});

c.appendChild(chart);
